import React, { Component } from "react";
import axios from "axios";
import "./Service.css";

class Service extends Component {
    constructor(props) {
        super(props);
        this.state = {
            servicePage: null,
        };
    }

    componentDidMount() {
        fetch("http://localhost:3001/pages/6", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({}),
        })
            .then((response) => response.json())
            .then((page) => {
                console.log('Fetched page:', page);
                this.setState({ servicePage: page });
            })
            .catch((error) => console.error("Error fetching data:", error));
    }

    fetchData = async () => {
        try {
            const response = await axios.get("http://localhost:3001/trackipetmap");
            const { lat, lng } = response.data;
            console.log(response.data);
            window.location.href = `/map?lat=${lat}&lng=${lng}`;
        } catch (error) {
            console.error(error);
        }
    };

    render() {
        const { servicePage } = this.state;

        if (!servicePage) return <div>PAGE NOT FOUND</div>;

        let contentArray = [];
        try {
            contentArray = Array.isArray(servicePage.content) 
                ? servicePage.content 
                : JSON.parse(servicePage.content);
        } catch (error) {
            console.error('Error parsing content:', error);
            return <div>ERROR PARSING CONTENT</div>;
        }

        console.log('Content array:', contentArray);

        return (
            <div className="container">
                <div className="image-section"></div>
                <div className="paw"></div>
                <div className="content-section">
                    {contentArray.length > 0 ? (
                        <>
                            <p className="Hello">{contentArray[0]?.p}</p>
                            <p className="Miss">{contentArray[1]?.p}</p>
                        </>
                    ) : (
                        <div>No content available</div>
                    )}
                    <button className="location" onClick={this.fetchData}>
                        Pet's Location
                    </button>
                </div>
            </div>
        ); 
    }
}

export default Service;
